const preventDowngrade = async (newVersion, currentVersion) =&gt; {
  const versions = await CapacitorUpdater.getVersions();
  if (versions.current.buildNumber &gt; newVersion.buildNumber) {
    throw new Error('Downgrade attempt detected');
