      await InAppReview.requestReview();

      // Store the request timestamp
      await Preferences.set({
        key: 'lastReviewRequest',
        value: Date.now().toString()
      });
    } catch (error) {
      console.log('Review prompt not shown:', error);
    }
  }
}

